# Homebrew formula for algoscope. Generated by scripts/update-tap.sh from the GitHub Release; do not
# edit the copy in the tap by hand.
class Algoscope < Formula
  desc "Terminal workbench for data structures, algorithms and system design"
  homepage "https://github.com/kokko-ng/algoscope"
  version "0.2.0"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/kokko-ng/algoscope/releases/download/v0.2.0/algoscope-v0.2.0-aarch64-apple-darwin.tar.gz"
      sha256 "b9a3bbf508f2ab2f6e2c1f339f0377af5bcb1b69dd1fc73820e935962ac2abcc"
    end
    on_intel do
      url "https://github.com/kokko-ng/algoscope/releases/download/v0.2.0/algoscope-v0.2.0-x86_64-apple-darwin.tar.gz"
      sha256 "0b196b8743185cf64f84672da031689f4546265cb8e9e43e632bb901bee588ad"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/kokko-ng/algoscope/releases/download/v0.2.0/algoscope-v0.2.0-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "00bde8648828c92a89aafcacd4371be9f53be673a96c8a9995beb961c4148f09"
    end
    on_intel do
      url "https://github.com/kokko-ng/algoscope/releases/download/v0.2.0/algoscope-v0.2.0-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "a9fec7c3fc352c6c456248c99d00af517d483872174e8d52fad2567db7ca9433"
    end
  end

  # solutions run on Python; pin the interpreter so a system Python older than 3.10 is never used
  depends_on "python@3.13"

  def install
    libexec.install "algoscope"
    (bin/"algoscope").write_env_script libexec/"algoscope",
      ALGOSCOPE_PYTHON: Formula["python@3.13"].opt_bin/"python3.13"
    doc.install "README.md"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/algoscope --version")
    assert_match "challenges checked, 0 with problems", shell_output("#{bin}/algoscope check-content --topic estimation")
  end
end
